import { AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef, Component, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertService, WaitService } from 'nmce';
import { Subject, Subscription, fromEvent, takeUntil } from 'rxjs';
import { PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { AppConfigConstants } from '../../environments/environment';
import { AUTH_STATUSES } from '../_authServices/tokenInterceptor';
import { LangSubjectService, StaticContentReloadSubjectService } from '../_services/types';
import { APP_DI_CONFIG } from '../app-config';
import { APP_STATUSES } from '../app-statuses';
import { BasicDataLoaderService } from '../shared/basicDataLoader.service';
import { MainComponentBase } from '../shared/mainBase.directive';
import { ViewSettingsDialogService } from '../shared/view-settings.component';

import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { AuthServicesModule } from '../_authServices/authServices.module';
import { LoginDialogService } from '../home/login.component';
import { NGMDModule } from '../ngmd.module';
import { AllMetaServiceModule } from '../shared/allMetaService.module';
import { MainButtonsComponent } from "../shared/main-buttons.component";
import { ChronicleForReaderComponent } from './chronicle-for-reader.component';

@Component({
	selector: 'main-for-reader',
	templateUrl: './main-for-reader.component.html',
	standalone: true,
	changeDetection: ChangeDetectionStrategy.OnPush,
	imports: [CommonModule,
		FormsModule,
		ReactiveFormsModule,
		NGMDModule, AllMetaServiceModule,
		AuthServicesModule,
		ChronicleForReaderComponent, MainButtonsComponent],
	providers: [BasicDataLoaderService, ViewSettingsDialogService, LoginDialogService,
	]
})
/**
 * Combining toolbar and ChronicleForReader.
 */
export class MainForReaderComponent extends MainComponentBase implements OnInit, OnDestroy, AfterViewInit {
	staticContentReloadSubscription: Subscription;
	private unsubscriber: Subject<void> = new Subject<void>();

	get loggedIn() {
		return AUTH_STATUSES.loggedIn;
	}

	get updateAvailable() {
		return APP_STATUSES.swUpdateAvailable;
	}

	get staticReadonlyHasSecondary() {
		if (AppConfigConstants.staticDatas) {
			return AppConfigConstants.staticReadonly && AppConfigConstants.staticDatas[APP_DI_CONFIG.currentStaticDataIndex].secondaryFilename;
		} else {
			return false;
		}
	}

	get convertZHButtonEnabled() {
		return this.isChinese &&
			(this.staticReadonlyHasSecondary || (!AppConfigConstants.staticReadonly && !this.loggedIn));
	}

	/**
	 * Toggle in UI will update this, and then alter APP_DI_CONFIG.sOrT.
	 * True to do conversion either s to t, or t to s.
	 */
	get convertZH(): boolean {
		return APP_DI_CONFIG.sOrT ? true : false;
	}
	set convertZH(v: boolean) {
		if (v) {
			if (APP_DI_CONFIG.defaultWrittenLanguage === 'zh-Hans') {
				APP_DI_CONFIG.sOrT = 's2t'; //so to tell the service to translate from S to T
				APP_DI_CONFIG.currentZhWritten = this.convertZH ? 'zh-Hant' : 'zh-Hans';
				console.debug('Current lang switched to: ' + APP_DI_CONFIG.currentZhWritten);
			} else if (APP_DI_CONFIG.defaultWrittenLanguage === 'zh-Hant') {
				APP_DI_CONFIG.sOrT = 't2s';// from T to S.
				APP_DI_CONFIG.currentZhWritten = this.convertZH ? 'zh-Hans' : 'zh-Hant';
				console.debug('Current lang switched to: ' + APP_DI_CONFIG.currentZhWritten);
			} else {
				APP_DI_CONFIG.sOrT = undefined;
			}
		} else {
			APP_DI_CONFIG.sOrT = undefined;
			if (APP_DI_CONFIG.defaultWrittenLanguage?.indexOf('zh-') >= 0) {
				APP_DI_CONFIG.currentZhWritten = APP_DI_CONFIG.defaultWrittenLanguage;
				console.debug('Current lang switched back to: ' + APP_DI_CONFIG.currentZhWritten);
			}
		}
	}

	get isChinese() {
		return APP_DI_CONFIG.defaultWrittenLanguage.indexOf('zh-') >= 0;
	}

	get jianFanIcon() {
		if (APP_DI_CONFIG.defaultWrittenLanguage === 'zh-Hans') {
			return this.convertZH ? 'c_jian' : 'c_fan';
		} else if (APP_DI_CONFIG.defaultWrittenLanguage === 'zh-Hant') {
			return this.convertZH ? 'c_fan' : 'c_jian';
		}

		return this.convertZH ? 'c_jian' : 'c_fan';
	}

	constructor(
		protected activatedRoute: ActivatedRoute,
		protected alertService: AlertService,
		protected poemsService: PoemsApp_Controllers_Client.Poems,
		protected basicDataLoaderService: BasicDataLoaderService,
		protected langSubjectService: LangSubjectService,
		protected waitService: WaitService,
		private viewSettingsDialogService: ViewSettingsDialogService,
		private staticContentReloadSubjectService: StaticContentReloadSubjectService,
		private router: Router,
		private ref: ChangeDetectorRef,
	) {
		super(activatedRoute, alertService, basicDataLoaderService, langSubjectService, waitService);
		console.debug('MainForReaderComponent created. IsSmallScreen: ' + this.isSmallScreen);

		this.staticContentReloadSubscription = this.staticContentReloadSubjectService.getMessage().subscribe(
			d => {
				this.reload();
			}
		);
	}

	ngOnInit() {
		console.debug('MainForReaderComponent init.');

		history.pushState(null, ''); //disable back

		fromEvent(window, 'popstate').pipe(
			takeUntil(this.unsubscriber)
		).subscribe((_) => {
			history.pushState(null, '');
			console.debug(`Not allow to go back to login`);
		});
	}

	ngOnDestroy() {
		this.staticContentReloadSubscription.unsubscribe();
		this.unsubscriber.next();
		this.unsubscriber.complete();

		super.ngOnDestroy();
	}

	ngAfterViewInit() {
		super.ngAfterViewInitShared();
		this.reload(); //here since the chronicle-for-reader component may be unavailable in ngOnInit()
		if (AUTH_STATUSES.loggedIn) {
			this.router.navigate(['/authoredit']);
			this.ref.detectChanges();
			console.info("Signed in already. Editor mode now.");
		}

		this.ref.detectChanges();
	}

	protected loadBriefs() {
		if (AppConfigConstants.staticReadonly) {
			this.basicDataLoaderService.allMetaService!.getBriefsOfPoems().subscribe(
				data => {
					if (!APP_DI_CONFIG.usePublished) {
						data.sort((x, y) => x.title!.localeCompare(y.title!, APP_DI_CONFIG.defaultWrittenLanguage)); //for zh-Hans, Pinyin, for zh-Hant, number of stokes.
					}

					this.poemBriefs = data;
					this.poemsLoadedSignal.set(true);
					this.ref.detectChanges(); //this will force the contained chronicleForReader component's poemBriefs input to update. Otherwise, chronicle may still use the old reference
					//this.chronicle!.listAllPoemBriefs();
					//this.ref.detectChanges(); no needed.
					console.debug('loadBriefs of statiReadonly done');
					this.waitService.setWait({ loading: false });
				}
			);
		} else {
			this.poemsService.getBriefsOfPoems(APP_DI_CONFIG.convertZhHandler).subscribe(
				{
					next: data => {
						if (data) {
							if (!APP_DI_CONFIG.usePublished) {
								data.sort((x, y) => x.title!.localeCompare(y.title!, APP_DI_CONFIG.defaultWrittenLanguage)); //for zh-Hans, Pinyin, for zh-Hant, number of stokes.
							}

							this.poemBriefs = data;							
							this.poemsLoadedSignal.set(true);
							this.ref.detectChanges();// faster than zone.run, so child component chronicle get the input data right away.
						}

						this.waitService.setWait({ loading: false });
					},
					error: error => {
						this.waitService.setWait({ loading: false });
						this.alertService.error(error);
					}
				}
			);
		}
	}

	showViewSettings() {
		this.viewSettingsDialogService.open();
	}

	/**
	 * Toggle for static readonly
	 */
	toogleChineseST() {
		this.convertZH = !this.convertZH;
		if (this.staticReadonlyHasSecondary) {
			APP_DI_CONFIG.isSecondary = !APP_DI_CONFIG.isSecondary;
		} 
		
		this.broadcastLangSubject();
		this.reload();
	}

	private broadcastLangSubject(){
		if (APP_DI_CONFIG.currentZhWritten) {
			console.info(`broadcastLangSubject currentZhWritten ${APP_DI_CONFIG.currentZhWritten}`);
			this.langSubjectService.emit(APP_DI_CONFIG.currentZhWritten);
		} else {
			this.langSubjectService.emit(APP_DI_CONFIG.defaultWrittenLanguage);
		}
	}

}
