import { Routes } from '@angular/router';
import { AlbumsForReaderComponent } from './albums-for-reader.component';
import { MainForReaderComponent } from './main-for-reader.component';
import { ReaderIndexComponent } from './reader-index.component';

export const READ_VIEW_ROUTES: Routes = [
	{ path: 'author/:authorIdx', component: MainForReaderComponent },

	{
		path: '', component: ReaderIndexComponent,
		children: [
			{ path: '', component: MainForReaderComponent },
			{ path: 'chronicle', component: MainForReaderComponent },
			{ path: 'albums', component: AlbumsForReaderComponent },
		]
	},
];
