import { ScrollDispatcher } from '@angular/cdk/scrolling';
import { CommonModule, Location } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, OnDestroy } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { Title } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertService, DataComponentDialogService } from 'nmce';
import { Subscription } from 'rxjs';
import { PoemsApp_Controllers_Client } from 'src/clientapi/WebApiNG2ClientAuto';
import { LangSubjectService, PoemAssociationsChangedSubjectService, PoemDeletedSubjectService, StaticContentReloadSubjectService } from '../_services/types';
import { NGMDModule } from '../ngmd.module';
import { AllMetaService } from '../shared/all-meta.service';
import { AllMetaServiceModule } from '../shared/allMetaService.module';
import { ChronicleViewComponentBase } from '../shared/chronicleBase.directive';
import { PoemViewerComponent } from "../shared/poemViewer.component";

@Component({
	selector: 'chronicle-for-reader',
	templateUrl: './chronicle-for-reader.component.html',
	changeDetection: ChangeDetectionStrategy.OnPush,
	standalone: true,
	imports: [CommonModule,
		FormsModule,
		ReactiveFormsModule,
		NGMDModule, AllMetaServiceModule,
		PoemViewerComponent],
	providers: [
	]
})
export class ChronicleForReaderComponent extends ChronicleViewComponentBase implements OnDestroy {
	staticContentReloadSubscription: Subscription;

	constructor(
		protected router: Router,
		protected location: Location,
		protected activatedRoute: ActivatedRoute,
		protected poemsService: PoemsApp_Controllers_Client.Poems,
		protected alertService: AlertService,
		protected dataComponentDialogService: DataComponentDialogService,
		protected poemDeletedSubjectService: PoemDeletedSubjectService,
		protected poemAssociationsChangedSubjectService: PoemAssociationsChangedSubjectService,
		private staticContentReloadSubjectService: StaticContentReloadSubjectService,
		protected langSubjectService: LangSubjectService,
		protected title: Title,
		protected ref: ChangeDetectorRef,
		protected scrollDispatcher: ScrollDispatcher,
		protected allMetaService?: AllMetaService,
	) {
		super(router, location, activatedRoute, poemsService, alertService, dataComponentDialogService, langSubjectService, title, ref, scrollDispatcher, allMetaService);
		this.staticContentReloadSubscription = this.staticContentReloadSubjectService.getMessage().subscribe(
			d => {
				this.currentPoem = {};
				this.filterMode=0;
				this.clearKeywords();
				this.closeTree();
				this.hideTagsPanel();
				this.ref.detectChanges();
			}
		);
	}

	ngOnDestroy() {
		this.staticContentReloadSubscription.unsubscribe();
		super.ngOnDestroy();
	}
}

